-- 5. Atributos enriquecidos
INSERT INTO atributo_enriquecido (id_atractivo, descripcion_corta, duracion_horas, costo_min_pen, costo_max_pen,
       id_dificultad, id_accesibilidad, horario_texto, hora_apertura, hora_cierre,
       temporada_texto, todo_el_anio, mes_inicio, mes_fin, requiere_validacion)
SELECT a.id_atractivo, v.descr, v.dur, v.cmin, v.cmax, v.dif, v.acc, v.hor, v.ha::time, v.hc::time,
       v.tem, v.todo, v.mi, v.mf, v.val FROM (VALUES
 ('REC-00001','Templo virgen de la merced figura en la base regional en el distrito de Juanjui, provincia de Mariscal Caceres. El interés se relaciona con las expresiones de fe y el patrimonio local. La visita debe respetar las celebraciones religiosas y los horarios de apertura de la administración. La descripción es provisional y requiere validación local.',0.50::numeric,NULL::numeric,NULL::numeric,3,1,NULL,NULL,NULL,NULL,FALSE,NULL::smallint,NULL::smallint,TRUE),
 ('REC-00002','Alameda turistica de juanjui. Paseo urbano sobre el antiguo espacio aeroportuario, con monumentos y áreas de recreación que permiten conocer parte de la identidad local. Se propone para un paseo de observación del entorno urbano y de la vida local. La permanencia puede combinarse con otros espacios cercanos según las preferencias del visitante.',1.00::numeric,0.00::numeric,0.00::numeric,3,4,'06:00 a.m. - 10:30 p.m.','06:00','22:30','Todo el año (según ficha; sujeto al clima)',TRUE,NULL::smallint,NULL::smallint,FALSE),
 ('REC-00003','Galeria fotografica so2 jorge leon linares figura en la base regional en el distrito de Huicungo, provincia de Mariscal Caceres. Su interés principal corresponde a la interpretación cultural y al aprendizaje. La visita debe ajustarse a los ambientes abiertos y a las actividades disponibles durante la jornada. La descripción es provisional y requiere validación local.',0.75::numeric,NULL::numeric,NULL::numeric,3,1,NULL,NULL,NULL,NULL,FALSE,NULL::smallint,NULL::smallint,TRUE),
 ('REC-00004','Rodales de manchinga figura en la base regional en el distrito de San Pablo, provincia de Bellavista. El interés propuesto corresponde al paisaje y la conservación del entorno. La definición del circuito, las actividades permitidas y el acceso requiere coordinación con los responsables del recurso. La descripción es provisional y requiere validación local.',1.00::numeric,NULL::numeric,NULL::numeric,1,1,NULL,NULL,NULL,NULL,FALSE,NULL::smallint,NULL::smallint,TRUE),
 ('REC-00005','Boulevard turistico quillosisa. Paseo junto al río Uquihua que combina paisaje ribereño, espacios para caminar y expresiones de la artesanía riojana. Se propone para un paseo de observación del entorno urbano y de la vida local. La permanencia puede combinarse con otros espacios cercanos según las preferencias del visitante.',1.00::numeric,0.00::numeric,0.00::numeric,3,1,'07:30 a.m. - 09:00 p.m.','07:30','21:00','Todo el año (según ficha; sujeto al clima)',TRUE,NULL::smallint,NULL::smallint,FALSE),
 ('REC-00006','Cascada lagunas gemelas de sacanche figura en la base regional en el distrito de Sacanche, provincia de Huallaga. El interés principal corresponde a las caídas de agua y al paisaje natural. El recorrido debe ajustarse al estado del sendero, la lluvia y las condiciones de ingreso. La descripción es provisional y requiere validación local.',2.00::numeric,NULL::numeric,NULL::numeric,1,1,NULL,NULL,NULL,NULL,FALSE,NULL::smallint,NULL::smallint,TRUE),
 ('REC-00007','Comunidad saludable miguel grau. Comunidad con actividades productivas y espacios de venta de artesanías y plantas ornamentales. Las experiencias organizadas se coordinan por separado. El interés se relaciona con la vida comunitaria y las expresiones culturales locales. Las experiencias organizadas deben acordarse con la población o con los responsables de recibir visitantes.',2.00::numeric,0.00::numeric,0.00::numeric,3,1,'08:00 a.m. - 05:00 p.m.','08:00','17:00','Todo el año (según ficha; sujeto al clima)',TRUE,NULL::smallint,NULL::smallint,FALSE),
 ('REC-00008','Rio aguas claras. Sector de río cuyo acceso final incluye una caminata aproximada de quince minutos. Ofrece contacto con el paisaje del Alto Mayo. Su interés se vincula al paisaje acuático y al entorno natural. Los servicios de navegación, baño u otras actividades deben confirmarse de manera independiente con los responsables locales.',1.50::numeric,2.00::numeric,2.00::numeric,3,1,'08:00 a.m. - 05:00 p.m.','08:00','17:00','Todo el año (según ficha; sujeto al clima)',TRUE,NULL::smallint,NULL::smallint,FALSE),
 ('REC-00009','Sendero royal sunangel. Sendero de bosque nublado orientado a la observación de aves. La torre de observación y el acceso a la trocha tienen tarifas diferenciadas. El interés propuesto corresponde al paisaje y la conservación del entorno. La definición del circuito, las actividades permitidas y el acceso requiere coordinación con los responsables del recurso.',3.00::numeric,30.00::numeric,30.00::numeric,4,1,'06:00 a.m. - 06:00 p.m.','06:00','18:00','Todo el año (según ficha; sujeto al clima)',TRUE,NULL::smallint,NULL::smallint,FALSE),
 ('REC-00010','Cascadas de progreso - la banda de shilcayo. Conjunto de cuatro caídas de agua dentro de un entorno boscoso. El acceso peatonal indicado en la ficha dura alrededor de veinticinco minutos. El interés principal corresponde a las caídas de agua y al paisaje natural. El recorrido debe ajustarse al estado del sendero, la lluvia y las condiciones de ingreso.',2.00::numeric,10.00::numeric,10.00::numeric,4,1,'08:00 a.m. - 03:00 p.m.','08:00','15:00','Todo el año (según ficha; sujeto al clima)',TRUE,NULL::smallint,NULL::smallint,FALSE),
 ('REC-00011','Cascadas lagrimas de la novia. Circuito con varias caídas de agua y distintos niveles de recorrido. Llegar a la primera cascada requiere menos esfuerzo que completar la visita. El interés principal corresponde a las caídas de agua y al paisaje natural. El recorrido debe ajustarse al estado del sendero, la lluvia y las condiciones de ingreso.',2.00::numeric,5.00::numeric,5.00::numeric,4,1,'08:00 a.m. - 04:00 p.m.','08:00','16:00','Todo el año (según ficha; sujeto al clima)',TRUE,NULL::smallint,NULL::smallint,FALSE),
 ('REC-00012','El aguajal laguna el doreo. Espacio recreativo asociado a una laguna y vegetación de aguajal. Las actividades especiales y el uso de instalaciones pueden generar pagos adicionales. Su interés se vincula al paisaje acuático y al entorno natural. Los servicios de navegación, baño u otras actividades deben confirmarse de manera independiente con los responsables locales.',2.00::numeric,0.00::numeric,0.00::numeric,3,4,'09:00 a.m. - 06:00 p.m.','09:00','18:00','Todo el año (según ficha; sujeto al clima)',TRUE,NULL::smallint,NULL::smallint,FALSE),
 ('REC-00013','Cascada chorros calientes. Afloramientos de agua caliente vinculados al circuito de Selva Alegre. El tramo peatonal requiere tiempo adicional y coordinación con responsables locales. El interés principal corresponde a las caídas de agua y al paisaje natural. El recorrido debe ajustarse al estado del sendero, la lluvia y las condiciones de ingreso.',3.00::numeric,NULL::numeric,NULL::numeric,4,1,'09:00 a.m. - 04:00 p.m.','09:00','16:00','Todo el año (según ficha; sujeto al clima)',TRUE,NULL::smallint,NULL::smallint,FALSE),
 ('REC-00014','Mirador turistico juan huido. Mirador que permite observar Juanjuí y el paisaje del Huallaga. El acceso descrito incluye una caminata desde el entorno urbano. Se propone como punto de observación del paisaje y fotografía. El tiempo real de permanencia y el esfuerzo dependen del acceso habilitado y de las condiciones meteorológicas.',1.50::numeric,0.00::numeric,0.00::numeric,4,1,'Sin horario fijo publicado; visita diurna sugerida hasta 17:00',NULL,NULL,'Todo el año (según ficha; sujeto al clima)',TRUE,NULL::smallint,NULL::smallint,FALSE),
 ('REC-00015','Jardin zoobotanico amazonia. Jardín de interés botánico y faunístico que reúne vegetación amazónica y espacios de interpretación de la naturaleza en el entorno de Moyobamba. El interés propuesto corresponde al paisaje y la conservación del entorno. La definición del circuito, las actividades permitidas y el acceso requiere coordinación con los responsables del recurso.',1.50::numeric,10.00::numeric,10.00::numeric,3,1,'09:00 a.m. - 04:00 p.m.','09:00','16:00','Todo el año (según ficha; sujeto al clima)',TRUE,NULL::smallint,NULL::smallint,FALSE),
 ('REC-00016','Cascadas pucayacu. Circuito natural con tres caídas accesibles y un tramo peatonal cercano a media hora. La lluvia puede modificar las condiciones del sendero. El interés principal corresponde a las caídas de agua y al paisaje natural. El recorrido debe ajustarse al estado del sendero, la lluvia y las condiciones de ingreso.',2.00::numeric,5.00::numeric,5.00::numeric,4,1,'08:00 a.m. - 03:30 p.m.','08:00','15:30','Todo el año (según ficha; sujeto al clima)',TRUE,NULL::smallint,NULL::smallint,FALSE),
 ('REC-00017','Catarata shihui. Catarata situada dentro del Parque Nacional Río Abiseo. Su visita forma parte de un recorrido fluvial que requiere autorización y organización previa. El interés principal corresponde a las caídas de agua y al paisaje natural. El recorrido debe ajustarse al estado del sendero, la lluvia y las condiciones de ingreso.',2.00::numeric,NULL::numeric,NULL::numeric,1,1,'09:00 a.m. - 04:00 p.m.','09:00','16:00','Meses específicos; consultar administración',FALSE,NULL::smallint,NULL::smallint,FALSE),
 ('REC-00018','Cerro tamburco. Elevación con vistas del paisaje riojano. La subida demanda esfuerzo y la ficha señala la necesidad de contratar un orientador local. Se propone como punto de observación del paisaje y fotografía. El tiempo real de permanencia y el esfuerzo dependen del acceso habilitado y de las condiciones meteorológicas.',4.00::numeric,0.00::numeric,0.00::numeric,5,1,'07:00 a.m. - 05:00 p.m.','07:00','17:00','Todo el año (según ficha; sujeto al clima)',TRUE,NULL::smallint,NULL::smallint,FALSE),
 ('REC-00019','Llanteria bird´s. Emprendimiento de observación de aves del Alto Mayo. La visita se coordina con el propietario y puede variar según el circuito seleccionado. El interés propuesto corresponde al paisaje y la conservación del entorno. La definición del circuito, las actividades permitidas y el acceso requiere coordinación con los responsables del recurso.',2.00::numeric,30.00::numeric,30.00::numeric,3,1,'06:00 a.m. - 06:00 p.m.','06:00','18:00','Junio–diciembre',FALSE,6::smallint,12::smallint,FALSE),
 ('REC-00020','Cueva cascada escondida. Cavidad natural que combina exploración subterránea y una cascada interior. El ingreso publicado incluye implementos y acompañamiento para la actividad. El interés principal corresponde a las caídas de agua y al paisaje natural. El recorrido debe ajustarse al estado del sendero, la lluvia y las condiciones de ingreso.',2.50::numeric,20.00::numeric,20.00::numeric,5,1,'09:00 a.m. - 04:00 p.m.','09:00','16:00','Abril–enero',FALSE,4::smallint,1::smallint,FALSE),
 ('REC-00021','Cascada urkuchaki. Conjunto de caídas de agua al que se llega por un sendero de aproximadamente dos kilómetros. El comité local solicita coordinación anticipada. El interés principal corresponde a las caídas de agua y al paisaje natural. El recorrido debe ajustarse al estado del sendero, la lluvia y las condiciones de ingreso.',3.00::numeric,5.00::numeric,5.00::numeric,4,1,'08:00 a.m. - 05:00 p.m.','08:00','17:00','Todo el año (según ficha; sujeto al clima)',TRUE,NULL::smallint,NULL::smallint,FALSE),
 ('REC-00022','Mirador el mono y la gata. Punto de observación del paisaje con acceso general libre. El sector específico para observar aves se cobra de forma independiente. Se propone como punto de observación del paisaje y fotografía. El tiempo real de permanencia y el esfuerzo dependen del acceso habilitado y de las condiciones meteorológicas.',1.00::numeric,0.00::numeric,0.00::numeric,3,1,'05:30 a.m. - 05:00 p.m.','05:30','17:00','Todo el año (según ficha; sujeto al clima)',TRUE,NULL::smallint,NULL::smallint,FALSE),
 ('REC-00023','Fundo alto nieva - rioja. Espacio de bosque nublado con zonas de observación de colibríes y otras aves. Cada modalidad tiene condiciones y precios propios. La experiencia se relaciona con actividades productivas locales y aprendizaje. Las visitas, talleres, degustaciones y compras deben coordinarse según la atención disponible y el servicio elegido.',2.00::numeric,30.00::numeric,30.00::numeric,3,1,'06:00 a.m. - 06:00 p.m.','06:00','18:00','Todo el año (según ficha; sujeto al clima)',TRUE,NULL::smallint,NULL::smallint,FALSE),
 ('REC-00024','Reserva privada aconabikh. Reserva privada orientada al contacto con el bosque y la observación de aves. La tarifa varía según la procedencia del visitante. El interés propuesto corresponde al paisaje y la conservación del entorno. La definición del circuito, las actividades permitidas y el acceso requiere coordinación con los responsables del recurso.',3.00::numeric,30.00::numeric,30.00::numeric,4,1,'07:30 a.m. - 05:00 p.m.','07:30','17:00','Todo el año (según ficha; sujeto al clima)',TRUE,NULL::smallint,NULL::smallint,FALSE),
 ('REC-00025','Cascada lluvia perpetua. Cascada del entorno natural de Soritor cuya visita requiere coordinar con la oficina local de turismo y confirmar las condiciones del acceso. El interés principal corresponde a las caídas de agua y al paisaje natural. El recorrido debe ajustarse al estado del sendero, la lluvia y las condiciones de ingreso.',NULL::numeric,NULL::numeric,NULL::numeric,1,1,'09:00 a.m. - 03:00 p.m.','09:00','15:00','Junio–octubre (orientativo; confirmar clima)',FALSE,6::smallint,10::smallint,FALSE),
 ('REC-00026','Cascada piscina de los reyes. Caídas de agua con pozas naturales dentro del circuito de Selva Alegre. El acceso final permite una caminata breve antes de la permanencia. El interés principal corresponde a las caídas de agua y al paisaje natural. El recorrido debe ajustarse al estado del sendero, la lluvia y las condiciones de ingreso.',2.00::numeric,7.00::numeric,7.00::numeric,3,1,'08:30 a.m. - 04:30 p.m.','08:30','16:30','Todo el año (según ficha; sujeto al clima)',TRUE,NULL::smallint,NULL::smallint,FALSE),
 ('REC-00027','Mirador del rio tioyacu. Mirador asociado al paisaje del río Tioyacu. Constituye un recurso diferente de la naciente y ofrece recorridos guiados con tarifas adicionales. Se propone como punto de observación del paisaje y fotografía. El tiempo real de permanencia y el esfuerzo dependen del acceso habilitado y de las condiciones meteorológicas.',2.00::numeric,5.00::numeric,5.00::numeric,4,1,'08:00 a.m. - 05:00 p.m.','08:00','17:00','Todo el año (según ficha; sujeto al clima)',TRUE,NULL::smallint,NULL::smallint,FALSE),
