-- 8. Trazabilidad de fuentes
INSERT INTO fuente_dato (id_atractivo, id_fuente, campo, fecha_verificacion, observacion)
SELECT a.id_atractivo, f.id_fuente, 'catalogo_base', a.fecha_corte, 'Fecha de corte del inventario oficial'
FROM atractivo a CROSS JOIN fuente f WHERE f.tipo_fuente = 'oficial';
INSERT INTO fuente_dato (id_atractivo, id_fuente, campo, observacion)
SELECT a.id_atractivo, f.id_fuente, c.campo, 'Atributo enriquecido; pendiente de verificación local'
FROM atractivo a CROSS JOIN fuente f
CROSS JOIN (VALUES ('descripcion_corta'),('duracion_horas'),('costo'),('dificultad'),('accesibilidad'),
                   ('horario'),('temporada'),('etiquetas'),('publico')) c(campo)
WHERE f.tipo_fuente = 'estimacion_equipo';

-- 9. Correcciones de calidad detectadas en el CSV (quedan registradas en el historial)
INSERT INTO historial_actualizacion (tabla, registro_id, operacion, campo, valor_anterior, valor_nuevo, motivo)
SELECT 'atractivo', id_atractivo::text, 'U', 'longitud', '77.503803190', '-77.503803190',
       'Longitud positiva en el CSV (fuera de Perú); se corrige el signo. Validar con la ficha oficial.'
FROM atractivo WHERE codigo_recurso = 'REC-00195';
INSERT INTO fuente_dato (id_atractivo, id_fuente, campo, observacion)
SELECT a.id_atractivo, f.id_fuente, 'ubicacion', 'Signo de longitud corregido por el equipo; pendiente de validar'
FROM atractivo a CROSS JOIN fuente f WHERE a.codigo_recurso = 'REC-00195' AND f.tipo_fuente = 'estimacion_equipo';

COMMIT;

